from html.parser import HTMLParser

class FAQParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.examples = []
        self.stack = []
        self.current = None
        self.ids = set()
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if 'id' in attrs:
            self.ids.add(attrs['id'])
        classes = attrs.get('class', '').split()
        if tag == 'div' and 'example' in classes:
            self.current = {'buttons': [], 'details': []}
            self.examples.append(self.current)
        if self.current is not None and tag == 'button':
            self.current['buttons'].append(attrs)
        if self.current is not None and tag == 'div' and 'details' in classes:
            self.current['details'].append(attrs)
        self.stack.append((tag, self.current if tag == 'div' and 'example' in classes else None))
    def handle_endtag(self, tag):
        for i in range(len(self.stack)-1, -1, -1):
            if self.stack[i][0] == tag:
                opened_example = self.stack[i][1]
                del self.stack[i:]
                if opened_example is not None:
                    self.current = None
                return

parser = FAQParser()
parser.feed(open('index.html', encoding='utf-8').read())
assert len(parser.examples) == 6, len(parser.examples)
for index, example in enumerate(parser.examples, 1):
    assert len(example['buttons']) == 1, (index, example)
    assert len(example['details']) == 1, (index, example)
    controls = example['buttons'][0].get('aria-controls')
    assert controls in parser.ids, (index, controls)
print('FAQ structure OK')
