for (const [i, match] of examples.entries()) {
  const block = match[1];
  if ((block.match(/class="question"/g) || []).length !== 1) throw new Error(`Example ${i + 1} missing one question button`);
  if ((block.match(/class="details"/g) || []).length !== 1) throw new Error(`Example ${i + 1} missing one details container`);
  const controls = block.match(/aria-controls="([^"]+)"/)?.[1];
  if (!controls || !html.includes(`id="${controls}"`)) throw new Error(`Example ${i + 1} has invalid aria-controls`);
}
console.log('FAQ structure OK');
