const path = require("node:path");
const { chromium } = require("playwright");

const pagePath = path.resolve(__dirname, "..", "index.html");
const html = fs.readFileSync(pagePath, "utf8");
const axePath = require.resolve("axe-core/axe.min.js");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.setContent(html, { waitUntil: "load" });
  await page.addScriptTag({ path: axePath });

  const structure = await page.evaluate(() => {
    const examples = Array.from(document.querySelectorAll(".example"));
    return {
      mainCount: document.querySelectorAll("main").length,
      h1Count: document.querySelectorAll("h1").length,
      examples: examples.length,
      invalidExamples: examples
        .map((example, index) => {
          const button = example.querySelector(".question");
          const details = example.querySelector(".details");
          return {
            index: index + 1,
            questionCount: example.querySelectorAll(".question").length,
            detailsCount: example.querySelectorAll(".details").length,
            expanded: button?.getAttribute("aria-expanded"),
            hidden: details?.hidden,
            controls: button?.getAttribute("aria-controls"),
            detailsId: details?.id,
          };
        })
        .filter(
          (item) =>
            item.questionCount !== 1 ||
            item.detailsCount !== 1 ||
            item.expanded !== "false" ||
            item.hidden !== true ||
            item.controls !== item.detailsId,
        ),
    };
  });

  const axeResult = await page.evaluate(async () => window.axe.run());
  const wcagViolations = axeResult.violations.filter(
    (violation) => !violation.tags.includes("best-practice"),
  );

  await browser.close();

  const failures = [];

  if (structure.mainCount !== 1) {
    failures.push(`Expected one main landmark, found ${structure.mainCount}.`);
  }

  if (structure.h1Count !== 1) {
    failures.push(`Expected one h1, found ${structure.h1Count}.`);
  }

  if (structure.examples !== 6) {
    failures.push(`Expected six FAQ examples, found ${structure.examples}.`);
  }

  if (structure.invalidExamples.length > 0) {
    failures.push(`Invalid FAQ disclosure state: ${JSON.stringify(structure.invalidExamples)}`);
  }

  if (wcagViolations.length > 0) {
    failures.push(
      JSON.stringify(
        wcagViolations.map((violation) => ({
          id: violation.id,
          impact: violation.impact,
          targets: violation.nodes.map((node) => node.target),
        })),
      ),
    );
  }

  if (failures.length > 0) {
    console.error(failures.join("\n"));
    process.exit(1);
  }

  console.log("Accessibility tests passed.");
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
